import assert from 'node:assert/strict';
import { readFile } from 'node:fs/promises';
import test from 'node:test';

import {
  loadCustomerSupportInstruction,
  runSupportAgent,
} from './support-agent.js';

test('loads the canonical instruction for both Responses calls', async () => {
  const requests = [];
  const responsesClient = {
    responses: {
      create: async (request) => {
        requests.push(request);
        return { id: `response-${requests.length}` };
      },
    },
  };

  await runSupportAgent(responsesClient, 'Where is order 123?');

  assert.equal(requests.length, 2);
  assert.equal(requests[0].instructions, requests[1].instructions);
  assert.equal(requests[0].instructions, await loadCustomerSupportInstruction());
  assert.equal(
    requests[0].instructions,
    await readFile(
      new URL('../moldea/agents/customer-support/instruction.md', import.meta.url),
      'utf8',
    ),
  );
  assert.equal(
    requests[1].input,
    'Continue helping the customer using only information already provided.',
  );
});

